package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.*;import com.ruoyi.medical.persistence.mapper.*;
import java.math.*;import java.time.*;import java.util.*;import java.util.function.Function;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Actual service/cursor/schema; SQL and already source-aware metadata authority are doubled. No body reads. */
class DocumentRevisionDirectoryServiceTest{
 static String id(int i){return String.format("00000000-0000-4000-8000-%012d",i);}static final String HASH="a".repeat(64);
 final EnterpriseAccess access=mock(EnterpriseAccess.class);final EnterpriseAccess.Admission a=mock(EnterpriseAccess.Admission.class);final ApplicationSessionIdentity.Verified subject=mock(ApplicationSessionIdentity.Verified.class);
 final PermissionMapper permissions=mock(PermissionMapper.class);final ResourceReadAuthority resources=mock(ResourceReadAuthority.class);final DocumentReadService documents=mock(DocumentReadService.class);final DocumentRevisionDirectoryMapper mapper=mock(DocumentRevisionDirectoryMapper.class);
 final DocumentRevisionDirectoryPolicy policy=new DocumentRevisionDirectoryPolicy(true,2,2,2,2,60);final DocumentRevisionDirectoryCursor cursors=new DocumentRevisionDirectoryCursor(policy);final LocalDateTime now=LocalDateTime.of(2026,10,18,0,0);
 final DocumentRevisionDirectoryService service;final DocumentRevisionDirectoryMapper.Head head=new DocumentRevisionDirectoryMapper.Head(id(1),id(4),id(5),id(6),BigInteger.ONE);
 DocumentRevisionDirectoryServiceTest()throws Exception{
  when(a.context()).thenReturn(new BusinessSessionProtocol.Context(id(1),"1","1","1"));when(a.actorId()).thenReturn(id(2));when(subject.sessionId()).thenReturn(id(3));
  when(access.execute(eq(subject),any())).thenAnswer(c->{Function<EnterpriseAccess.Admission,Object> f=c.getArgument(1);return f.apply(a);});
  when(permissions.resourceOwner("DOCUMENT",id(5))).thenReturn(List.of(new PermissionProtocol.OwnerRow(id(5),id(4))));when(mapper.head(anyMap())).thenReturn(List.of(head));
  service=new DocumentRevisionDirectoryService(access,permissions,resources,documents,mapper,policy,cursors,new PermissionSchema());
 }
 DocumentRevisionDirectoryMapper.Row row(int n){return new DocumentRevisionDirectoryMapper.Row(id(n),HASH,id(2),now.minusDays(n),null,HASH);}
 void allow(int n)throws Exception{var proof=mock(DocumentReadService.MetadataRead.class);when(proof.header()).thenReturn(new DocumentReadProtocol.Header(id(1),id(4),id(5),id(n),id(6),BigInteger.ONE,"DRAFT","ACTIVE",id(10),id(11),id(12),id(13),id(14),HASH,"private/key","v1",id(15),id(16),id(17),id(18),BigInteger.ZERO,HASH,id(2),now.minusDays(n),"INTERNAL"));when(documents.authorizeMetadata(a,"1",id(5),id(n))).thenReturn(proof);}
 @Test void emptyDirectoryHasNoInventedCountOrBodyRead()throws Exception{var v=service.read(subject,"1",id(5),2,null);assertTrue(v.required("complete").booleanValue());assertTrue(v.required("items").isEmpty());assertFalse(v.has("total"));verifyNoInteractions(documents);}
 @Test void authorizedHistoricalAndCurrentEntriesHaveExactOriginalRoutes()throws Exception{when(mapper.scan(anyMap())).thenReturn(List.of(row(6),row(7)));allow(6);allow(7);var v=service.read(subject,"1",id(5),2,null);assertTrue(v.required("items").get(0).required("is_current").booleanValue());assertFalse(v.required("items").get(1).required("is_current").booleanValue());assertTrue(v.required("items").get(1).required("read_url").textValue().endsWith(id(7)));verify(documents,times(2)).requireMetadataCurrent(eq(a),any());verify(documents,never()).readFixed(any(),any(),any(),any());}
 @Test void deniedScanCanReturnEmptyPageWithOpaqueContinuation()throws Exception{when(mapper.scan(anyMap())).thenReturn(List.of(row(6),row(7),row(8)));when(documents.authorizeMetadata(eq(a),eq("1"),eq(id(5)),anyString())).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));var v=service.read(subject,"1",id(5),2,null);assertTrue(v.required("items").isEmpty());assertFalse(v.required("complete").booleanValue());assertFalse(v.required("next_cursor").isNull());assertFalse(v.toString().contains(id(7)));}
 @Test void onlyExplicitUnreadableSourceErrorsAreHidden()throws Exception{when(mapper.scan(anyMap())).thenReturn(List.of(row(7)));for(ErrorCode code:List.of(ErrorCode.SOURCE_MISSING,ErrorCode.SOURCE_NOT_READY)){doThrow(new TenantAccessException(code)).when(documents).authorizeMetadata(a,"1",id(5),id(7));assertTrue(service.read(subject,"1",id(5),2,null).required("items").isEmpty());}}
 @Test void CorruptOrUnavailableMetadataIsNotSilentlyFiltered()throws Exception{when(mapper.scan(anyMap())).thenReturn(List.of(row(7)));for(ErrorCode code:List.of(ErrorCode.CONTENT_MISMATCH,ErrorCode.OBJECT_UNAVAILABLE)){doThrow(new TenantAccessException(code)).when(documents).authorizeMetadata(a,"1",id(5),id(7));assertEquals(code,assertThrows(TenantAccessException.class,()->service.read(subject,"1",id(5),2,null)).code());}}
 @Test void registryMismatchFailsBeforeDisclosure()throws Exception{when(mapper.scan(anyMap())).thenReturn(List.of(new DocumentRevisionDirectoryMapper.Row(id(7),HASH,id(2),now,null,null)));assertEquals(ErrorCode.CONTENT_MISMATCH,assertThrows(TenantAccessException.class,()->service.read(subject,"1",id(5),2,null)).code());verifyNoInteractions(documents);}
 @Test void staleContextNeverEnumerates()throws Exception{assertEquals(ErrorCode.CONTEXT_CHANGED,assertThrows(TenantAccessException.class,()->service.read(subject,"2",id(5),2,null)).code());verifyNoInteractions(mapper,resources,documents);}
 @Test void revokedAcceptedProofAbortsWholePage()throws Exception{when(mapper.scan(anyMap())).thenReturn(List.of(row(7)));allow(7);doThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED)).when(documents).requireMetadataCurrent(eq(a),any());assertEquals(ErrorCode.ACCESS_DENIED,assertThrows(TenantAccessException.class,()->service.read(subject,"1",id(5),2,null)).code());}
 @Test void referenceOverflowDoesNotTruncateSuccessfulPage()throws Exception{when(mapper.scan(anyMap())).thenReturn(List.of(row(7)));allow(7);when(mapper.checks(anyMap())).thenReturn(List.of(id(20),id(21),id(22)));assertEquals(ErrorCode.CONTEXT_LIMIT,assertThrows(TenantAccessException.class,()->service.read(subject,"1",id(5),2,null)).code());}
 @Test void cursorCannotCrossSessionOrHeadWatermark()throws Exception{when(mapper.scan(anyMap())).thenReturn(List.of(row(6),row(7),row(8)));allow(6);allow(7);String token=service.read(subject,"1",id(5),2,null).required("next_cursor").textValue();when(subject.sessionId()).thenReturn(id(99));assertEquals(ErrorCode.CURSOR_INVALID,assertThrows(TenantAccessException.class,()->service.read(subject,"1",id(5),2,token)).code());when(subject.sessionId()).thenReturn(id(3));when(mapper.head(anyMap())).thenReturn(List.of(new DocumentRevisionDirectoryMapper.Head(id(1),id(4),id(5),id(9),BigInteger.TWO)));assertEquals(ErrorCode.CURSOR_INVALID,assertThrows(TenantAccessException.class,()->service.read(subject,"1",id(5),2,token)).code());}
 @Test void invalidPageLimitRejectsBeforeDatabase()throws Exception{assertThrows(SchemaRejection.class,()->service.read(subject,"1",id(5),0,null));assertThrows(SchemaRejection.class,()->service.read(subject,"1",id(5),3,null));verifyNoInteractions(access,mapper);}

 @Test void validCursorAdvancesAfterLastScannedCandidate()throws Exception{when(mapper.scan(anyMap())).thenAnswer(c->{Map<String,Object> v=c.getArgument(0);assertEquals(id(2),v.get("userId"));assertEquals(id(4),v.get("projectId"));if(v.get("afterDocumentRevision")==null)return List.of(row(6),row(7),row(8));assertEquals(id(7),v.get("afterDocumentRevision"));assertEquals(now.minusDays(7),v.get("afterCreatedAt"));return List.of(row(8));});allow(6);allow(7);allow(8);String token=service.read(subject,"1",id(5),2,null).required("next_cursor").textValue();var page=service.read(subject,"1",id(5),2,token);assertTrue(page.required("complete").booleanValue());assertEquals(id(8),page.required("items").get(0).required("document_revision").textValue());}
 @Test void cursorExpiryAndEvictionAreExplicit()throws Exception{class MutableClock extends Clock{Instant now=Instant.EPOCH;public java.time.ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(java.time.ZoneId z){return this;}public Instant instant(){return now;}}var clock=new MutableClock();var cache=new DocumentRevisionDirectoryCursor(policy,clock);var owner=new DocumentRevisionDirectoryCursor.Owner(id(1),id(2),id(3),"1","1","1",id(5),"1",2);var position=new DocumentRevisionDirectoryCursor.Position(now,id(6));String first=cache.issue(owner,position);cache.issue(owner,position);cache.issue(owner,position);assertEquals(ErrorCode.CURSOR_EXPIRED,assertThrows(TenantAccessException.class,()->cache.resolve(first,owner)).code());String latest=cache.issue(owner,position);clock.now=Instant.EPOCH.plusSeconds(61);assertEquals(ErrorCode.CURSOR_EXPIRED,assertThrows(TenantAccessException.class,()->cache.resolve(latest,owner)).code());}

 @Test void oversizedReferenceCandidateFailsCapacityBeforeEvenKnownSourceDenial()throws Exception{when(mapper.scan(anyMap())).thenReturn(List.of(row(7)));when(mapper.checks(anyMap())).thenReturn(List.of(id(20),id(21),id(22)));doThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED)).when(documents).authorizeMetadata(a,"1",id(5),id(7));assertEquals(ErrorCode.CONTEXT_LIMIT,assertThrows(TenantAccessException.class,()->service.read(subject,"1",id(5),2,null)).code());verify(documents,never()).authorizeMetadata(any(),any(),any(),any());}
 @Test void missingOrDriftedRegistrySentinelNeverBecomesEmptySuccessfulHistory()throws Exception{for(String sentinel:Arrays.asList(null,"b".repeat(64))){when(mapper.scan(anyMap())).thenReturn(List.of(new DocumentRevisionDirectoryMapper.Row(id(7),HASH,id(2),now,null,sentinel)));assertEquals(ErrorCode.CONTENT_MISMATCH,assertThrows(TenantAccessException.class,()->service.read(subject,"1",id(5),2,null)).code());}verifyNoInteractions(documents);}
}
